{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret er generisk og rammer ikke vejledningens kerne: sygehistorik, seneste journalnotater/epikriser og støtteforanstaltninger. Det nævner en 'lægeerklæring', et 'handicapid-kort' og 'skolepædagogiske vurderinger', som ikke er nævnt i kilderne. Det udelader, at en personlig redegørelse kan supplere, og at dokumentationen som minimum skal indeholde journaler (§ 37, stk. 3). Svaret kan give det indtryk, at en lægeerklæring er tilstrækkelig."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret mangler flere kritiske elementer. Sygehistorik og seneste journalnotater/epikriser nævnes ikke. Udrednings- og behandlingsforløb samt aktuelle symptomer er ikke med. Støtteforanstaltninger og skånehensyn er ikke nævnt. Den personlige redegørelse er helt udeladt. Kun 'medicinsk dokumentation' fra sundhedsprofessionelle rammer løst det lægefaglige materiale."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret forholder sig direkte til spørgsmålet om, hvilken dokumentation ansøgeren kan sende, og giver en liste. Indholdet er upræcist, men svaret er ikke irrelevant."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde som lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer dokumenttyper uden støtte i materialet: handicapid-kort og skolepædagogiske vurderinger. Det kræver også en lægeerklæring om påvirkning af dagligdagen. Det anbefaler desuden at søge råd hos en læge for at sikre, at dokumenterne er 'korrekt udfyldt'. Intet af dette fremgår af kilderne."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at de seneste foreliggende oplysninger kan være ældre. Det siger heller ikke, at eksemplerne ikke er kumulative krav, eller at en personlig redegørelse kun supplerer og ikke erstatter det lægefaglige minimum. Det angiver ikke, at listen af eksempler ikke er udtømmende."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: det opregner dokumenttyper og afslutter med en anbefaling. Der er ingen indbyrdes modsigelser, selv om indholdet er mangelfuldt."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger overvejende 'kan' om, hvad ansøgeren kan sende, hvilket ikke gør noget absolut. Ordet 'vigtigt' bruges om at søge råd, men det gør ikke dokumentationskrav absolutte. Svaret overser dog, at vejledningen kræver de seneste lægefaglige oplysninger, men det er et indholdsproblem, ikke en modalitetsfejl."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret behandler dokumentation ved medfødt funktionsnedsættelse generelt. Det nævner ikke sygehistorik, seneste journalnotater, ofte manglende nyere dokumentation eller personlig redegørelse. Det giver ingen eksempler på medfødte funktionsnedsættelser."
    },
    "A35": {
      "label": "partial",
      "reason": "Svaret nævner lægeligt/medicinsk materiale, men ikke epikriser, journalnoter, udrednings- og behandlingsforløb, aktuelle symptomer, støtteafgørelser/skånehensyn eller den personlige redegørelse som alternativ. Dækningen er derfor kun overfladisk."
    }
  },
  "overall_notes": "Svaret er generisk og uden kilder. Det udelader de centrale elementer i vejledningens afsnit 4.3 og tilføjer ustøttede dokumenttyper (handicapid-kort, skolepædagogiske vurderinger). Da der ikke er angivet nogen kilde, er C04 not_met, mens C05 og C06 er not_assessable."
}

